#include <iostream>
#include <cstddef>
void bounds(const int* a,std::size_t n,int& lo,int& hi){lo=hi=a[0];for(std::size_t i=1;i<n;++i){if(a[i]<lo)lo=a[i];if(a[i]>hi)hi=a[i];}}
int main(){
int a[]={4,-2,9,1};int lo,hi;bounds(a,4,lo,hi);std::cout<<lo<<" "<<hi;
}

